c:FRA ?= {
		set_variable = {
			name = ce_french_empire_variable
		}

		effect_starting_technology_tier_1_tech = yes

		set_tax_level = medium

		effect_starting_technology_tier_1_tech = yes

		activate_law = law_type:law_monarchy
		activate_law = law_type:law_wealth_voting
		activate_law = law_type:law_freedom_of_conscience
		activate_law = law_type:law_women_own_property
		activate_law = law_type:law_per_capita_based_taxation
		activate_law = law_type:law_appointed_bureaucrats
		activate_law = law_type:law_cultural_exclusion
		activate_law = law_type:law_protectionism
		activate_law = law_type:law_interventionism
		activate_law = law_type:law_public_schools
		activate_law = law_type:law_per_capita_based_taxation
		activate_law = law_type:law_colonial_resettlement
		activate_law = law_type:law_dedicated_police
		activate_law = law_type:law_professional_army
		activate_law = law_type:law_poor_laws
		activate_law = law_type:law_censorship # The July Monarchy was already backtracking on promises made in 1830
		activate_law = law_type:law_national_guard
		activate_law = law_type:law_tenant_farmers
		activate_law = law_type:law_combination_acts # Legacy of the Napoleonic Code and 1791 Le Chapelier Law
		activate_law = law_type:law_colonial_slavery # Slavery in French colonies was only abolished in 1848

		active_law:lawgroup_distribution_of_power ?= { # Wealth Voting
			add_amendment = {
				type = amendment_200_franc_suffrage
				sponsor = PREV.ig:ig_industrialists
				cooldown = 48
			}
		}

		set_institution_investment_level = {
			institution = institution_schools
			level = 2
		}

		set_institution_investment_level = {
			institution = institution_police
			level = 1
		}

		set_institution_investment_level = {
			institution = institution_colonial_affairs
			level = 1
		}

		ig:ig_landowners ?= { # Victor de Broglie was Prime Minister until February 22, 1836
			add_ruling_interest_group = yes
			set_interest_group_name = ig_ce_napoleonic_faction
		}

		ig:ig_armed_forces ?= {
			add_ruling_interest_group = yes
		}

		ig:ig_industrialists = {
			add_ruling_interest_group = yes
			#set_interest_group_name = ig_ce_industrial_faction
		}		

		ig:ig_devout ?= { 
			set_interest_group_name = ig_catholic_church
		}

		ig:ig_intelligentsia ?= {}

		add_company = company_type:company_dmc
		company:company_dmc = {
			set_company_establishment_date = 1746.1.1
			set_company_state_region = s:STATE_ALSACE_LORRAINE
		}

		set_variable = free_elections_var
		active_law:lawgroup_distribution_of_power ?= { # Wealth Voting - the July Monarchy couldn't properly rig an election to save their lives
			add_amendment = {
				type = amendment_tradition_of_free_elections
				sponsor = PREV.ig:ig_intelligentsia
			}
		}

		add_company = company_type:company_john_cockerill
		company:company_john_cockerill = {
			set_company_establishment_date = 1825.1.1
			set_company_state_region = s:STATE_WALLONIA
		}

		set_variable = ce_participated_in_polish_problem

		set_variable = {
			name = fra_republic_counter
			value = 1
		}

		set_variable = {
			name = bonapartist_restoration_var
		}

		set_variable = {
			name = one_true_french_dynasty
		}

		set_variable = ce_france_support_napoleon # grant trigger to bonapartist


		add_modifier = {
			name = modifier_haitian_independence_payments_4
		}

		if = {
			limit = {
				has_dlc_feature = voice_of_the_people_content
			}
			# add_journal_entry = {
			# 	type = 
			# }
			add_journal_entry = {
				type = je_ce_unstable_imperium
			}
			add_journal_entry = {
				type = je_conquest_of_algeria
			}
		}

		set_variable = free_elections_var
	}

