c:POR ?= {
		set_next_election_date = 1836.7.17

		effect_starting_technology_tier_3_tech = yes
		effect_starting_politics_conservative = yes

		add_technology_researched = atmospheric_engine
		add_technology_researched = empiricism
		add_technology_researched = napoleonic_warfare
		add_technology_researched = stock_exchange
		add_technology_researched = mass_communication

		add_taxed_goods = g:liquor
		add_taxed_goods = g:coffee

		set_import_tariff_level = { 
			goods = g:artillery
			level = high_subventions
		}
		set_import_tariff_level = { 
			goods = g:small_arms
			level = high_subventions
		}	

		activate_law = law_type:law_monarchy
		activate_law = law_type:law_freedom_of_conscience # The Constitutional Charter of 1826 established some sort of freedom of conscience
		activate_law = law_type:law_oligarchy # Elections of 1836 were both rigged and carried out indirectly
		activate_law = law_type:law_elected_bureaucrats # Assemblies were elected, but governors were appointed by the central government. Nonetheless, Elected Bureaucrats + Oligarchy is the best way to handle these indirect elections
		activate_law = law_type:law_land_based_taxation
		activate_law = law_type:law_national_supremacy
		activate_law = law_type:law_mercantilism
		activate_law = law_type:law_national_guard
		activate_law = law_type:law_diplomatic_navy
		activate_law = law_type:law_no_police # Portugal had Local Police prior to 1833, but it was replaced with the National Guard during the Liberal Wars
		activate_law = law_type:law_interventionism
		activate_law = law_type:law_censorship # Nominally, freedom of expression existed, but in practice this was not observed
		activate_law = law_type:law_colonial_exploitation
		activate_law = law_type:law_colonial_slavery
		activate_law = law_type:law_latifundias
		activate_law = law_type:law_charitable_health_system
		activate_law = law_type:law_poor_laws # Constitutional Charter of 1826 guaranteed public relief
		activate_law = law_type:law_public_schools # Constitutional Charter of 1826 guaranteed free education for all citizens

		active_law:lawgroup_distribution_of_power ?= { # Oligarchy
			add_amendment = {
				type = amendment_chamber_of_gentleman_deputies
				sponsor = PREV.ig:ig_petty_bourgeoisie
				cooldown = 24 # Product of the 1828 Charter
			}
		}

		initialise_caciquismo_effect = yes

		set_tax_level = medium

		set_institution_investment_level = {
			institution = institution_colonial_affairs
			level = 2
		}

		ig:ig_petty_bourgeoisie ?= {
			add_ruling_interest_group = yes
		}

		ig:ig_armed_forces = {
			add_ideology = ideology_liberal_praetorian
			add_ruling_interest_group = yes
		}

		set_variable = { name = recent_coup_or_revolution_var value = 2 }

		if = {
			limit = {
				has_dlc_feature = ip4_content
			}
			add_journal_entry = { type = je_devorismo }
			add_journal_entry = { type = je_second_liberalism }
			add_modifier = { name = modifier_legacy_of_the_liberal_wars days = long_modifier_time is_decaying = yes }
		}
	}

